class _MeshEnv:
    def __init__(self) -> None:
        self.mesh_stack: List[DeviceMesh] = []
        self.child_to_parent_mapping: Dict[DeviceMesh, DeviceMesh] = {}

    def get_current_mesh(self) -> "DeviceMesh":
        if len(self.mesh_stack) == 0:
            raise RuntimeError("No device mesh is currently active!")
        return self.mesh_stack[-1]

    def create_child_mesh(
        self, device_mesh: "DeviceMesh", mesh_dim: int, mesh_dim_name: str
    ) -> "DeviceMesh":
        # swap the current dim to the last dim then reshape to flatten out other
        # dims, so we can just extract the list of ranks which contains cur_rank.
        cur_rank = device_mesh.get_rank()
        pg_ranks_by_dim = device_mesh.mesh.swapdims(-1, mesh_dim).reshape(
            -1, device_mesh.mesh.size(mesh_dim)
        )

        for mesh_1d in pg_ranks_by_dim:
            sub_mesh = DeviceMesh(
                device_mesh.device_type,
                mesh_1d,
                mesh_dim_names=(mesh_dim_name,),
                _init_process_groups=False,
            )
            if cur_rank in mesh_1d:
                res_sub_mesh = sub_mesh

        res_sub_mesh._dim_group_infos = [device_mesh._dim_group_infos[mesh_dim]]
        # Assign the current DeviceMesh as the parent of the child DeviceMesh.
        self.child_to_parent_mapping[res_sub_mesh] = device_mesh
        return res_sub_mesh

    def get_parent_mesh(self, device_mesh: "DeviceMesh") -> Optional["DeviceMesh"]:
        return self.child_to_parent_mapping.get(device_mesh, None)

    def get_parent_mesh_dim(self, device_mesh: "DeviceMesh") -> Optional[int]:
        """
        Return the index of the mesh dim in the parent mesh.
        The device_mesh passed in needs to be sliced out from a parent mesh.
        """
        parent_mesh = self.get_parent_mesh(device_mesh)
        child_mesh_dim_names = device_mesh.mesh_dim_names
        if parent_mesh and child_mesh_dim_names:
            assert (
                len(child_mesh_dim_names) == 1
            ), "The child mesh can only be a 1D mesh."
            child_mesh_dim_name = child_mesh_dim_names[0]
            if parent_mesh.mesh_dim_names:
                return parent_mesh.mesh_dim_names.index(child_mesh_dim_name)
        return None

    @staticmethod
    def num_devices_per_host(device_type: str) -> int:
        return _get_device_handle(device_type).device_count()

    @staticmethod
    def num_hosts(device_type: str) -> int:
        # ProcessGroup can't tell us this info so we have to infer it, assume
        # homogeneous hardware for now
        return get_world_size() // _MeshEnv.num_devices_per_host(device_type)

    _mesh_resources: _MeshEnv = _MeshEnv()

    def __getitem__(self, mesh_dim_name: str) -> "DeviceMesh":
        if self.mesh_stack:
            current_mesh = self.mesh_stack[-1]
            return current_mesh[mesh_dim_name]
        else:
            raise RuntimeError("No current device mesh to slice from.")

    def create_child_mesh(self, device_mesh: "DeviceMesh", mesh_dim: int, mesh_dim_name: str) -> "DeviceMesh":
        return _mesh_resources.create_child_mesh(device_mesh, mesh_dim, mesh_dim_name)

    def get_parent_mesh(self, device_mesh: "DeviceMesh") -> Optional["DeviceMesh"]:
        return _mesh_resources.get_parent_mesh(device_mesh)

    def get_parent_mesh_dim(self, device_mesh: "DeviceMesh") -> Optional[int]:
        return _mesh_resources.get_parent_mesh_dim(device_mesh)

    def get_current_mesh(self) -> "DeviceMesh":
        return _mesh_resources.get_current_mesh()

    def get_dim_groups(self, device_mesh: "DeviceMesh", mesh_dim: Optional[int] = None) -> Union[ProcessGroup, List[ProcessGroup]]:
        return device_mesh.get_dim_groups(mesh_dim)

    def size(self, device_mesh: "DeviceMesh", dim: Optional[int] = None) -> int:
        return device_mesh.size(dim)

    def get_rank(self, device_mesh: "DeviceMesh") -> int:
        return device_mesh.get_rank()

    def get_coordinate(self, device_mesh: "DeviceMesh") -> Optional[List[int]]:
        return device_mesh.get_coordinate()

    def __enter__(self) -> "DeviceMesh":
        if not self.mesh_stack:
            raise RuntimeError("No current device mesh to enter.")
