            conv = self.conv._conv_forward(input, scaled_weight, zero_bias)
            conv_orig = conv / scale_factor.reshape(bias_shape)
            conv_orig = conv_orig + self.conv.bias.reshape(bias_shape)
            conv = self.bn(conv_orig)
            return conv

