        self.kernel = kernel

    def codegen(self):
        code = CodeWriter()
        self._codegen_header(code)
        self._codegen_body(code)
        return code.code

    def _codegen_header(self, code):
        # Generate the header code for the kernel
        code.writeline(f"kernel {self.name} {self.kernel.name}")
        code.writeline("{" if self.kernel.is_parallel else "}")

        # Generate the input and output declarations
        for i, (input_var, output_var) in enumerate(zip(self.inputs, self.outputs)):
            if i > 0:
                code.writeline(",")
            code.writeline(f"  {input_var.name} = {output_var.name}")

        # Generate the iteration ranges
        if self.kernel.iteration_ranges:
            code.writeline("\n  iteration_ranges:")
            for range_name, range_obj in self.kernel.iteration_ranges.items():
                code.writeline(f"    {range_name}: {range_obj}")

        # Generate the kernel body
        if self.kernel.body:
            code.writeline("\n  body:")
