        return None

    from torch_tensorrt.fx.fx2trt import (  # type: ignore[import]
        InputTensorSpec,
        TRTInterpreter,
    )
    from torch_tensorrt.fx.passes.lower_basic_pass import (  # type: ignore[import]
        transform_setitem,
    )
