    def __init__(self, layout, inputs, constant_args):
        super().__init__(None, layout, inputs, constant_args)

    @classmethod
    def create(
        cls,
        x: "TensorBox",
        reduce_op: str,
        scatter_dim: int,
        tag: str,
        ranks: List[int],
